<template><div><div class="page-head"><div><h1>Orders</h1><p class="muted">Monitor and process customer orders.</p></div></div><div class="filters card"><Search :size="16"/><input v-model="q" placeholder="Search order or customer…"/><select v-model="status"><option value="">All statuses</option><option>Pending</option><option>Processing</option><option>Shipped</option><option>Delivered</option></select></div><section class="card table-card"><div class="table-wrap"><table class="table"><thead><tr><th>Order</th><th>Customer</th><th>Items</th><th>Total</th><th>Status</th><th>Date</th></tr></thead><tbody><tr v-for="o in filtered" :key="o.id"><td><RouterLink :to="`/orders/${o.id}`"><b>{{o.id}}</b></RouterLink></td><td>{{o.customer}}</td><td>{{o.items}}</td><td>{{format(o.total)}} EGP</td><td><span class="badge">{{o.status}}</span></td><td>{{o.date}}</td></tr></tbody></table></div></section></div></template>
<script setup lang="ts">import {computed,ref} from 'vue';import {RouterLink} from 'vue-router';import {Search} from 'lucide-vue-next';import {orders} from '../services/mock';const q=ref(''),status=ref('');const filtered=computed(()=>orders.filter(o=>(!q.value||`${o.id} ${o.customer}`.toLowerCase().includes(q.value.toLowerCase()))&&(!status.value||o.status===status.value)));const format=(n:number)=>new Intl.NumberFormat('en-EG').format(n)</script>
<style scoped>.filters{padding:10px 12px;display:flex;gap:10px;align-items:center;margin-bottom:14px}.filters input{border:0;outline:0;flex:1}.filters select{border:1px solid #ddd;border-radius:7px;padding:8px;background:#fff}.table-card{padding:0}.table a:hover{text-decoration:underline}</style>
